-- A claim's status: DRAFT when made, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT';
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: their due-total now (the figures of their claims that count, added
 * up, skipping n/a; n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
 * figure or has one under another grade in force on its date; each claim at its date's grade's rate; an overdue claim's late charge on top), as the screen shows it. Every claim of theirs that counts is bound to its figure now (a live
 * one at least the sheet's floor), never its late charge;
 * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
 * and the due-total and the sheet's today are kept as the last statement's.
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates,
            SettingsRepository settings, PersonRepository people, Out<Statement> statementOut) {
        List<Rate> all = rates.findAll(sheet.id());
        Settings sheetSettings = settings.find(sheet.id());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
            boolean counts = claim.counts(person.isHeld());
            if (counts) {
                counted++;
                if (claim.getSettledDue() != null || claim.getStatedDue() != null) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = ClaimFigure.of(claim, all, grade, sheetSettings, sheet.today());
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(person.gradeOn(sheet.today()))) fixed = true;
                // The due-total carries the late charge; the claim is bound to the figure under it.
                if (figure != null) total = total.add(figure).add(ClaimFigure.late(claim, figure, sheetSettings, sheet.today()));
                claim.bind(true, figure);
            } else {
                claim.bind(false, null);
            }
            claims.save(claim);
        }
        String dueTotal = Rate.inForce(all, person.gradeOn(sheet.today()), sheet.today()).isEmpty() && !fixed
                ? "n/a" : total.toPlainString();
        person.setStatements(person.getStatementCount() + 1, dueTotal, sheet.today());
        people.saveStatements(person);
        statementOut.set(new Statement(dueTotal, counted));
    }
}
    public record Figures(String name, String claimed, String dueTotal) {
        boolean sameFigures(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }

    /**
     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
     * and SETTLED, but not OPEN while they are on hold) added up; their due-total the figures of those claims added up, skipping n/a (a live figure is at least the sheet's floor; an overdue one gains its late
     * charge on {@code today}), and
     * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
     * figure or has one under the grade in force on its date when that is another grade. Each claim
     * takes the rate of the grade in force on its date. The
     * sheet's totals add these up, skipping n/a.
     */
    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
            RateRepository rates, Settings settings) {
        List<Rate> all = rates.findAll(sheetId);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!claim.counts(person.isHeld())) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || claim.getStatedDue() != null) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
                if (figure != null) due = due.add(figure);
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
            }
            boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            if (!none) dueTotal = dueTotal.add(due);
            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due)));
        }
        return new Rollup(figures, show(claimedTotal), show(dueTotal));
    }

    /**
     * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
     * figures changed (a person new since counts as changed), then a TOTALS line when either of the
     * sheet's totals changed.
     */
    public List<String> changesSince(Rollup before, String sheetId, String user) {
        List<String> lines = new ArrayList<>();
        String head = " sheet=" + sheetId + " by=" + user;
        people.forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + now.dueTotal());
            }
        });
        if (!claimedTotal.equals(before.claimedTotal()) || !dueTotal.equals(before.dueTotal())) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal);
        }
        return lines;
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim's status: DRAFT when made, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  corrects: string;
  roundDate: string;
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do, and
 * an OPEN one not while its person is on hold (`held`).
 */
export const counts = (c: Claim, held: boolean) => c.status === 'SETTLED' || (c.status === 'OPEN' && !held);

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * A claim number, as a correction names the claim it corrects: a sheet-wide number, or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN and SETTLED, but not OPEN of a person on hold:
 * `held` tells by person id) added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], held: (personId: string) => boolean): string {
  const cents = claims.filter((c) => counts(c, held(c.personId))).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
}

/**
 * An amount times a rate, divided by 100, rounded to two decimals (half up when `halfUp`, else half
 * to even), raised to the sheet's `floor` when below it; n/a with no rate (no floor applies to n/a).
 * Worked in whole numbers so no floating-point error creeps in. A correction (a negative amount)
 * takes no floor (`floor` null).
 */
export function due(amount: string, pct: string | null, floor: string | null, halfUp: boolean): string {
  if (pct === null) return NA;
  const rounded = percentOf(amount, pct, 1n, halfUp);
  if (floor === null) return showCents(rounded);
  const least = hundredths(floor);
  return showCents(rounded < least ? least : rounded);
}

/**
 * `times` × a percent of a two-decimal figure, in cents, rounded half up when `halfUp`, else half
 * to even (either symmetric about 0).
 */
function percentOf(figure: string, pct: string, times: bigint, halfUp: boolean): bigint {
  // cents × basis points is the due in millionths of a unit: 10000 of them to the cent.
  const signed = hundredths(figure) * hundredths(pct) * times;
  const x = signed < 0n ? -signed : signed;
  const cents = x / 10000n;
  const rest = x % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n)) ? cents + 1n : cents;
  return signed < 0n ? -rounded : rounded;
}

/**
 * What the late charge and a claim's rounding need: the sheet's late percent (two decimals), its
 * terms (days), its today (yyyy-MM-dd; '' until read) and its policy date (yyyy-MM-dd; '' for its
 * today).
 */
export type Late = { pct: string; terms: number; today: string; policyDate: string };

/**
 * Whether a claim's live figures round half up: it rounds by a date (its own, or for a correction
 * the date of the claim it corrects) before the sheet's policy date (its today when blank); on or
 * after it they round half to even.
 */
export function roundsHalfUp(claim: Claim, late: Late): boolean {
  const policy = late.policyDate !== '' ? late.policyDate : late.today;
  return (claim.roundDate || claim.date) < policy;
}

/** Whole days from one date (yyyy-MM-dd) to another, worked in UTC so no zone shifts it. */
function daysBetween(from: string, to: string): number {
  const utc = (date: string) => {
    const [y, m, d] = date.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/**
 * A claim's late charge on its `figure`: for an OPEN claim past its due-by (its date plus the
 * terms) on the sheet's today, the late percent of the figure for every full 30 days it is overdue,
 * rounded as the claim rounds; else nothing. A statement never binds it: it follows the sheet's today.
 */
function lateCharge(claim: Claim, figure: string, late: Late): bigint {
  if (claim.status !== 'OPEN' || figure === NA || late.today === '' || isCorrection(claim)) return 0n;
  const overdue = daysBetween(claim.date, late.today) - late.terms;
  const periods = overdue > 0 ? Math.floor(overdue / 30) : 0;
  return periods === 0 ? 0n : percentOf(figure, late.pct, BigInt(periods), roundsHalfUp(claim, late));
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/**
 * A claim's due: the one fixed when it was settled (its late charge frozen in), else the figure its
 * person's last statement bound it to, else its amount at the rate in force on its date, at least
 * the sheet's `floor`; an overdue claim's late charge added on top.
 */
export function claimDue(claim: Claim, pct: string | null, floor: string, late: Late): string {
  if (claim.due !== '') return claim.due;
  const figure = claim.stated ? claim.statedDue : due(claim.amount, pct, isCorrection(claim) ? null : floor, roundsHalfUp(claim, late));
  const charge = lateCharge(claim, figure, late);
  return charge === 0n ? figure : showCents(hundredths(figure) + charge);
}

/**
 * A person's due-total: the figures of their claims that count (none OPEN while they are `held`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement) or has a figure under another grade, in force on its date.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  held: boolean,
  floor: string,
  late: Late,
): string {
  const counted = claims.filter((c) => counts(c, held));
  const grade = gradeOn(grades, today);
  const kept = (c: Claim) => c.due !== '' || (c.stated && c.statedDue !== NA)
    || (gradeOn(grades, c.date) !== grade && rateOn(rates, gradeOn(grades, c.date), c.date) !== null);
  if (rateOn(rates, grade, today) === null && !counted.some(kept)) return NA;
  return sumDue(counted.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late)));
}

import { gradeOn } from '../people/people';
import type { GradeFrom } from '../people/people';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Late, Rate } from '../rates/rates';

/** A date (yyyy-MM-dd) and a number of days after it, as yyyy-MM-dd. Worked in UTC so no zone shifts it. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms (days). */
export const dueBy = (claim: Claim, terms: number): string => addDays(claim.date, terms);

/** Whether a claim is overdue: OPEN, and its due-by before the sheet's `today`. */
export const isOverdue = (claim: Claim, terms: number, today: string): boolean =>
  claim.status === 'OPEN' && today !== '' && dueBy(claim, terms) < today;

/**
 * A person's overdue claims that count (none while they are `held`, as an OPEN claim then counts in
 * no total): how many, and their due figures (with their late charge) added up, skipping n/a.
 */
export function personOverdue(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  terms: number,
  claims: Claim[],
  held: boolean,
  floor: string,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, held) && isOverdue(c, terms, today));
  return {
    count: overdue.length,
    total: sumDue(overdue.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late))),
  };
}

